      "filename": "app/core/error_handlers.py",
      "language": "python",
      "description": "Centralized error handler returning consistent JSON",
      "code": "from fastapi import Request
from fastapi.responses import JSONResponse
from fastapi import HTTPException

def register_error_handlers(app):
    @app.exception_handler(HTTPException)
    async def http_exception_handler(request: Request, exc: HTTPException):
        return JSONResponse(status_code=exc.status_code, content={'error': exc.detail, 'path': request.url.path})

    @app.exception_handler(Exception)
    async def general_exception_handler(request: Request, exc: Exception):
        return JSONResponse(status_code=500, content={'error': str(exc), 'path': request.url.path})"
    }
